<?php declare(strict_types=1);$slug=$_GET['slug']??'';if(!preg_match('/^[a-z0-9-]+$/',$slug)){http_response_code(404);exit('Not found');}$runtime=trim((string)getenv('CTI_RUNTIME_DIR'))?:__DIR__.'/.cti_runtime';$path=$runtime.'/cms/vendors.json';$data=is_file($path)?json_decode((string)file_get_contents($path),true):[];$v=null;foreach(($data['vendors']??[]) as $x){if(($x['slug']??'')===$slug&&($x['status']??'')==='published'){$v=$x;break;}}if(!$v){http_response_code(404);exit('Not found');}function h($x){return htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}$canonical='https://cybertechintelligence.com/vendors/'.$slug;$schema=['@context'=>'https://schema.org','@type'=>'Organization','name'=>$v['name'],'url'=>$v['website']??$canonical,'description'=>$v['summary']??''];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($v['name'])?> Vendor Intelligence | CyberTech Intelligence</title><meta name="description" content="<?=h($v['summary']??'')?>"><link rel="canonical" href="<?=h($canonical)?>"><meta property="og:title" content="<?=h($v['name'])?> Vendor Intelligence"><meta property="og:description" content="<?=h($v['summary']??'')?>"><meta property="og:url" content="<?=h($canonical)?>"><script type="application/ld+json"><?=json_encode($schema,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP)?></script><style>body{margin:0;background:#0b0d10;color:#f5f7fa;font:16px/1.7 system-ui,sans-serif}main{max-width:880px;margin:auto;padding:70px 24px}a,.meta{color:#21e6e6}h1{font-size:clamp(42px,7vw,72px);line-height:1.04}.dek{font-size:20px;color:#aeb6c2}.body{white-space:pre-wrap}</style></head><body><main><p><a href="/vendors.html">← Back to Vendor Intelligence</a></p><p class="meta"><?=h(strtoupper($v['category']??'Vendor'))?></p><h1><?=h($v['name'])?></h1><p class="dek"><?=h($v['summary']??'')?></p><article class="body"><?=h($v['body']??'')?></article></main></body></html>